package study.console;
import org.junit.*;import static org.junit.Assert.*;
import study.trade.*;import study.trade.TradeModels.*;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
import org.apache.ibatis.session.SqlSession;
public class TradeAdvancedFeaturesTest {
 private Database db;private TradeDatabase trade;
 @Before public void setup(){db=Boolean.getBoolean("trade.real")?Database.configured(false):Database.demo();trade=new TradeDatabase(db,true);trade.clearProductCache();}
 @After public void close(){if(db!=null)db.close();}
 private Product row(long id){var p=new Product();p.id=id;p.productName="补充实验商品";p.category="外设";p.brand="星河";p.brandId=1L;p.price=new BigDecimal("199.00");p.stock=10;p.saleStatus="在售";return p;}
 private long trial(){return -Math.abs(UUID.randomUUID().getMostSignificantBits()%1000000000000L)-100;}
 @Test public void dynamicTrimForeachChoose(){try(var s=trade.open()){var m=s.getMapper(study.trade.TradeMapper.class);var q=new ProductQuery();q.brandIds=List.of(1L,2L);q.minimum=new BigDecimal("200");q.maximum=new BigDecimal("5000");q.priceDesc=true;q.validate();var rows=m.findAdvanced(q);assertEquals(4,rows.size());assertTrue(rows.stream().allMatch(x->q.brandIds.contains(x.brandId)));for(int i=1;i<rows.size();i++)assertTrue(rows.get(i-1).price.compareTo(rows.get(i).price)>=0);System.out.println("动态条件 trim/foreach/choose："+rows);q.brandIds=List.of();q.minimum=null;q.maximum=null;q.priceDesc=false;assertEquals(10,m.findAdvanced(q).size());q.minimum=BigDecimal.TEN;q.maximum=BigDecimal.ONE;assertThrows(IllegalArgumentException.class,q::validate);}}
 @Test public void batchInsertAndSelectiveUpdateRollback(){long a=trial(),b=a-1;try(var s=trade.open()){var m=s.getMapper(study.trade.TradeMapper.class);assertEquals(2,m.insertBatch(List.of(row(a),row(b))));Product patch=new Product();patch.id=a;patch.price=new BigDecimal("188.00");assertEquals(1,m.updateSelective(patch));var read=m.findById(a);assertEquals(Integer.valueOf(10),read.stock);assertEquals(new BigDecimal("188.00"),read.price);System.out.println("foreach批量新增2条，trim局部更新后："+read);s.rollback(true);}try(var s=trade.open()){assertNull(s.getMapper(study.trade.TradeMapper.class).findById(a));assertNull(s.getMapper(study.trade.TradeMapper.class).findById(b));}}
 @Test public void lambdaConditionalPagination(){try(var s=trade.openPlus()){var w=new LambdaQueryWrapper<Product>().eq(Product::getCategory,"外设").ge(Product::getPrice,new BigDecimal("100")).orderByDesc(Product::getPrice).orderByAsc(Product::getId);var p=s.getMapper(ProductPlusMapper.class).selectPage(new Page<Product>(2,2),w);assertEquals(3,p.getTotal());assertEquals(2,p.getPages());assertEquals(1,p.getRecords().size());assertEquals(Long.valueOf(3),p.getRecords().get(0).id);System.out.println("Lambda分页：总数="+p.getTotal()+"，第2页="+p.getRecords());}}
 @Test public void autoFillAndOptimisticLock(){long id=trial();try(var s=trade.openPlus()){var m=s.getMapper(ProductPlusMapper.class);var p=row(id);assertEquals(1,m.insert(p));var initial=m.selectById(id);assertNotNull(initial.createTime);assertNotNull(initial.updateTime);assertEquals(Integer.valueOf(0),initial.version);Product stale=row(id);stale.version=0;initial.stock=15;initial.updateTime=LocalDateTime.of(2000,1,1,0,0);assertEquals(1,m.updateById(initial));stale.stock=99;assertEquals(0,m.updateById(stale));var current=m.selectById(id);assertEquals(Integer.valueOf(15),current.stock);assertEquals(Integer.valueOf(1),current.version);assertTrue(current.updateTime.isAfter(LocalDateTime.of(2000,1,1,0,0)));System.out.println("自动填充：创建="+current.createTime+"，更新="+current.updateTime+"；乐观锁version="+current.version+"，过期更新影响0行");s.rollback(true);}}
 @Test public void secondLevelCacheCommitAndSerializedCopies(){trade.sqlCounter().reset();Product first;try(var s=trade.open()){first=s.getMapper(study.trade.TradeMapper.class).findById(1);s.commit();}assertEquals(1,trade.sqlCounter().value());try(var s=trade.open()){var second=s.getMapper(study.trade.TradeMapper.class).findById(1);assertNotSame(first,second);assertEquals(first.productName,second.productName);s.commit();}assertEquals(1,trade.sqlCounter().value());System.out.println("二级缓存：跨会话查询2次，实际SELECT="+trade.sqlCounter().value()+"；序列化副本引用不同");}
 @Test public void rollbackDoesNotPublishSecondLevelCache(){trade.sqlCounter().reset();try(var s=trade.open()){s.getMapper(study.trade.TradeMapper.class).findById(1);s.rollback(true);}try(var s=trade.open()){s.getMapper(study.trade.TradeMapper.class).findById(1);s.commit();}assertEquals(2,trade.sqlCounter().value());System.out.println("回滚不发布缓存：实际SELECT="+trade.sqlCounter().value());}
 @Test public void plusDmlInvalidatesSharedXmlCache(){long id=trial();try{
  try(var s=trade.openPlus()){s.getMapper(ProductPlusMapper.class).insert(row(id));s.commit();}
  trade.sqlCounter().reset();try(var s=trade.open()){s.getMapper(study.trade.TradeMapper.class).findById(id);s.commit();}
  try(var s=trade.openPlus()){Product patch=new Product();patch.id=id;patch.stock=27;assertEquals(1,s.getMapper(ProductPlusMapper.class).updateById(patch));s.commit();}
  try(var s=trade.open()){assertEquals(Integer.valueOf(27),s.getMapper(study.trade.TradeMapper.class).findById(id).stock);s.commit();}
  assertEquals(2,trade.sqlCounter().value());System.out.println("MP提交修改后，XML缓存失效：SELECT="+trade.sqlCounter().value());
 }finally{try(var s=trade.openPlus()){s.getMapper(ProductPlusMapper.class).deleteById(id);s.commit();}}}
 @Test public void brandAssociationSummaryAndForeignKey()throws Exception{try(var s=trade.open()){var m=s.getMapper(study.trade.TradeMapper.class);var products=m.productsWithBrands();assertEquals(10,products.size());assertTrue(products.stream().allMatch(p->p.brandInfo!=null));assertEquals("星河",products.get(0).brandInfo.brandName);assertEquals(5,m.brandSummary().size());System.out.println("品牌association="+products.get(0).brandInfo);System.out.println("品牌统计="+m.brandSummary());}
  try(var c=db.tradeEnvironment().getDataSource().getConnection()){String t=c.getMetaData().storesUpperCaseIdentifiers()?"LAB_TRADE_PRODUCT":"lab_trade_product";var indexes=new HashSet<String>();try(var r=c.getMetaData().getIndexInfo(c.getCatalog(),null,t,false,false)){while(r.next())indexes.add(String.valueOf(r.getString("INDEX_NAME")).toLowerCase());}assertTrue(indexes.contains("idx_trade_brand"));assertTrue(indexes.contains("idx_trade_product_name"));boolean fk=false;try(var r=c.getMetaData().getImportedKeys(c.getCatalog(),null,t)){while(r.next())if("brand_id".equalsIgnoreCase(r.getString("FKCOLUMN_NAME")))fk=true;}assertTrue(fk);}
 }
}
